/**
 * Test stub for the `#i18n` WXT virtual module.
 *
 * WHY THIS EXISTS
 *
 * `#i18n` is generated by `wxt prepare` into `.wxt/i18n/`. Vitest cannot resolve
 * it, and that had a consequence far worse than a failing import:
 *
 *   1. Every `.tsx` that imports `#i18n` could never be loaded by a unit test.
 *   2. So those files were never *covered* — they went through the suite as
 *      "untested files".
 *   3. To report 0% for an untested file, vitest-coverage-v8 transforms it with
 *      its own pipeline. That transform cannot resolve `#i18n` either, and the
 *      provider swallows the failure (`.catch(() => null)` in `getSources`),
 *      falling back to reading the RAW `.tsx` off disk.
 *   4. It then feeds raw TSX to rollup's JavaScript-only parser, which fails on
 *      the type annotations, and logs "Excluding it from coverage" — while
 *      still exiting 0.
 *
 * Net effect: four components were silently absent from `coverage-final.json`,
 * and the coverage thresholds were computed over a smaller file set than
 * `vitest.config.ts` asks for. The gate was green while measuring less than it
 * claimed. `scripts/check-coverage-integrity.mjs` now fails the build if that
 * ever happens again; this alias is the actual fix.
 *
 * WHY IT IS NOT A STRING-CONCATENATION FAKE
 *
 * `t()` resolves the real key against the real `en.yml`, and applies the real
 * `$1`/`$2` substitutions. A test that renders a component therefore sees the
 * actual user-visible English copy, so assertions on that copy are meaningful
 * and a broken locale key surfaces as the raw key rather than silently
 * rendering something plausible.
 *
 * This is the same module for the whole suite (aliased in `vitest.config.ts`),
 * so a test that wants to assert on a specific string does not need a mock and
 * a test that wants to assert on copy keeps working.
 */

import { readFileSync } from "fs";
import { resolve } from "path";
import { load } from "js-yaml";

type LocaleTree = { [key: string]: string | LocaleTree };

const enYaml = load(
  readFileSync(resolve(__dirname, "../../src/locales/en.yml"), "utf-8")
) as LocaleTree;

/** Resolve a dotted key path (`"common.save"`) against the locale tree. */
function lookup(key: string): string | undefined {
  let node: string | LocaleTree | undefined = enYaml;
  for (const segment of key.split(".")) {
    if (node === undefined || typeof node === "string") return undefined;
    node = node[segment];
  }
  return typeof node === "string" ? node : undefined;
}

/**
 * Substitute `$1`, `$2`, … the way Chrome's i18n does.
 *
 * Accepts both the array form (`t(key, [a, b])`) and the bare-value form
 * (`t(key, n)`), because the codebase uses both — 34 call sites pass a second
 * argument and roughly half of them pass a non-array.
 */
function substitute(
  template: string,
  substitutions?: string | string[]
): string {
  const values = Array.isArray(substitutions)
    ? substitutions
    : substitutions === undefined
      ? []
      : [substitutions];

  return template.replace(/\$(\d+)/g, (match, index: string) => {
    const value = values[Number(index) - 1];
    // An unmatched placeholder is left verbatim, matching Chrome's behaviour,
    // so a missing substitution is visible in the rendered output.
    return value === undefined ? match : value;
  });
}

export const i18n = {
  /**
   * Translate `key`. Returns the key itself when it is missing from `en.yml`,
   * which makes a locale regression legible in a test failure instead of
   * rendering as an empty string.
   */
  t(key: string, substitutions?: string | string[]): string {
    const template = lookup(key);
    if (template === undefined) return key;
    return substitute(template, substitutions);
  },

  getUILanguage(): string {
    return "en-US";
  },

  getMessage(key: string, substitutions?: string | string[]): string {
    return i18n.t(key, substitutions);
  },
};

export default i18n;
